package com.franco.desco.application.pricing.service;import com.franco.desco.application.pricing.*;import com.franco.desco.application.pricing.port.in.PricingUseCase;import com.franco.desco.application.pricing.port.out.PricingPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.pricing.PricingModels;import java.util.List;
public final class PricingApplicationService implements PricingUseCase{private final PricingPersistencePort p;public PricingApplicationService(PricingPersistencePort p){this.p=p;}public AppResult<PageResult<PricingModels.Condition>>conditions(PricingCommands.ListConditions c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.conditions(c,i,m),"CONDICIONES_LISTADAS","CONDICIONES_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<Long>createCondition(PricingCommands.CreateCondition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.createCondition(c,i,m),"CONDICION_CREADA","CONDICION_NO_CREADA");}public AppResult<Void>updateCondition(PricingCommands.UpdateCondition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.updateCondition(c,i,m),"CONDICION_ACTUALIZADA","CONDICION_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>disableCondition(PricingCommands.DisableCondition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.disableCondition(c,i,m),"CONDICION_DESHABILITADA","CONDICION_NO_DESHABILITADA",AppStatus.BAD_REQUEST);}public AppResult<PageResult<PricingModels.Price>>prices(PricingCommands.ListPrices c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.prices(c,i,m),"PRECIOS_LISTADOS","PRECIOS_NO_LISTADOS",AppStatus.BAD_REQUEST);}public AppResult<Long>createPrice(PricingCommands.CreatePrice c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.createPrice(c,i,m),"PRECIO_CREADO","PRECIO_NO_CREADO");}public AppResult<Long>versionPrice(PricingCommands.VersionPrice c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.versionPrice(c,i,m),"PRECIO_VERSIONADO","PRECIO_NO_VERSIONADO");}public AppResult<List<PricingModels.PriceVersion>>history(PricingCommands.PriceHistory c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.history(c,i,m),"HISTORIAL_PRECIO_CARGADO","HISTORIAL_PRECIO_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}}
